{
  "meta": {
    "name": "RealEstateListings",
    "description": "A real estate listings platform for agents to post properties, buyers to inquire, with admin moderation and featured listings for premium agents."
  },
  "entities": [
    {
      "name": "Property",
      "ownable": true,
      "fields": [
        {
          "name": "address",
          "type": "string",
          "required": true
        },
        {
          "name": "price",
          "type": "number",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "bedrooms",
          "type": "integer"
        },
        {
          "name": "bathrooms",
          "type": "integer"
        },
        {
          "name": "squareFootage",
          "type": "integer"
        },
        {
          "name": "images",
          "type": "url",
          "required": true
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "pending_approval",
            "approved",
            "rejected",
            "sold"
          ],
          "default": "pending_approval"
        },
        {
          "name": "isFeatured",
          "type": "boolean",
          "default": false
        }
      ]
    },
    {
      "name": "Inquiry",
      "ownable": false,
      "fields": [
        {
          "name": "buyerName",
          "type": "string",
          "required": true
        },
        {
          "name": "buyerEmail",
          "type": "email",
          "required": true
        },
        {
          "name": "buyerPhone",
          "type": "string"
        },
        {
          "name": "message",
          "type": "text"
        },
        {
          "name": "inquiryDate",
          "type": "datetime",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "property",
          "kind": "manyToOne",
          "target": "Property",
          "required": true
        }
      ]
    },
    {
      "name": "Agent",
      "ownable": false,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "email",
          "type": "email",
          "required": true,
          "unique": true
        },
        {
          "name": "phone",
          "type": "string"
        },
        {
          "name": "company",
          "type": "string"
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "agent",
      "description": "Can post and manage their own properties, send inquiries.",
      "isDefault": true
    },
    {
      "name": "buyer",
      "description": "Can view properties and send inquiries."
    },
    {
      "name": "admin",
      "description": "Can moderate all properties and manage agents."
    },
    {
      "name": "premiumAgent",
      "description": "A premium agent with featured listing capabilities."
    }
  ],
  "permissions": [
    {
      "role": "agent",
      "entity": "Property",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "agent",
      "entity": "Inquiry",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "buyer",
      "entity": "Property",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "buyer",
      "entity": "Inquiry",
      "actions": [
        "create"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Property",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Inquiry",
      "actions": [
        "read",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Agent",
      "actions": [
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "premiumAgent",
      "entity": "Property",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "Properties List",
      "route": "/properties",
      "type": "list",
      "entity": "Property",
      "access": [
        "agent",
        "buyer",
        "admin",
        "premiumAgent"
      ]
    },
    {
      "name": "Property Detail",
      "route": "/properties/:id",
      "type": "detail",
      "entity": "Property",
      "access": [
        "agent",
        "buyer",
        "admin",
        "premiumAgent"
      ]
    },
    {
      "name": "New Property",
      "route": "/properties/new",
      "type": "form",
      "entity": "Property",
      "access": [
        "agent",
        "premiumAgent"
      ]
    },
    {
      "name": "Edit Property",
      "route": "/properties/:id/edit",
      "type": "form",
      "entity": "Property",
      "access": [
        "agent",
        "premiumAgent"
      ]
    },
    {
      "name": "New Inquiry",
      "route": "/inquiries/new/:propertyId",
      "type": "form",
      "entity": "Inquiry",
      "access": [
        "buyer"
      ],
      "fields": [
        "buyerName",
        "buyerEmail",
        "buyerPhone",
        "message"
      ]
    },
    {
      "name": "Agent Properties",
      "route": "/my-properties",
      "type": "list",
      "entity": "Property",
      "access": [
        "agent",
        "premiumAgent"
      ]
    },
    {
      "name": "Admin Dashboard",
      "route": "/admin/dashboard",
      "type": "dashboard",
      "access": [
        "admin"
      ],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Properties",
          "entity": "Property",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Pending Approvals",
          "entity": "Property",
          "metric": "count",
          "filter": { "status": "pending_approval" }
        },
        {
          "type": "stat",
          "label": "Total Inquiries",
          "entity": "Inquiry",
          "metric": "count"
        },
        {
          "type": "table",
          "label": "Recent Inquiries",
          "entity": "Inquiry",
          "limit": 5
        }
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true,
      "features": [
        "standard_listing"
      ]
    },
    {
      "name": "premium",
      "price": 50,
      "interval": "month",
      "features": [
        "featured_listing",
        "priority_support"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "featuredListingGate",
      "requiresPlan": "premium",
      "gates": {
        "features": [
          "featured_listing"
        ],
        "pages": [
          "New Property",
          "Edit Property"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "propertyOwnership",
      "entity": "Property"
    },
    {
      "type": "ownership",
      "id": "agentOwnership",
      "entity": "Agent"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
